function constructDistancedSequence(n) {
  const size = 2 * n - 1;
  const result = new Array(size).fill(0);
  const used = new Array(n + 1).fill(false);

  function place(index) {
    if (index === size) {
      return true;
    }
    if (result[index] !== 0) {
      return place(index + 1);
    }
    for (let value = n; value >= 1; value--) {
      if (used[value]) {
        continue;
      }
      const partner = value === 1 ? index : index + value;
      if (partner >= size || result[partner] !== 0) {
        continue;
      }
      used[value] = true;
      result[index] = value;
      result[partner] = value;
      if (place(index + 1)) {
        return true;
      }
      used[value] = false;
      result[index] = 0;
      result[partner] = 0;
    }
    return false;
  }

  place(0);
  return result;
}

