function constructDistancedSequence(n) {
  // Enumerate every valid arrangement by placing values 2..n (then 1) anywhere, and keep the largest.
  const size = 2 * n - 1;
  const cells = new Array(size).fill(0);
  let best = null;
  const bigger = (a, b) => {
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return a[i] > b[i];
    return false;
  };
  const go = (v) => {
    if (v === 1) {
      const free = cells.indexOf(0);
      cells[free] = 1;
      if (best === null || bigger(cells, best)) best = cells.slice();
      cells[free] = 0;
      return;
    }
    for (let p = 0; p + v < size; p++) {
      if (cells[p] || cells[p + v]) continue;
      cells[p] = cells[p + v] = v;
      go(v - 1);
      cells[p] = cells[p + v] = 0;
    }
  };
  go(n);
  return best;
}

